poem:
let i = Math.sqrt(-1);

console.assert(i === i);
console.assert(Object.is(i, i));

var west = -1;
var east = 1;

while (west !== east) {
    west /= 2;
    east /= 2;
}

Object.is(west, east);

function fine() {
    try {
        fine();
    } catch {
    }
}

fine();

function who() {
    return this;
}

who();
({ who }).who();
who.call(who);

self = {};
self . self = self;
other = structuredClone(self);
other.self === other && other.self !== self;

const classroom = document.all;

if (!classroom)
    for (const student of classroom)
        student.isConnected;
